INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3914348',2109,83,'P1','Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis','FEPESE - Per Of Crim (PCien SC)/PCien SC/Ciências Sociais Aplicadas/2026','Caderno Contabilidade Geral Parte 3','Considere o balanço patrimonial abaixo da Companhia Goiás: Companhia Goiás – Balanço Patrimonial – Valores em R$ ATIVO 31/12/2025 31/12/2024 PASSIVO e PL 31/12/2025 31/12/2024 Ativo Circulante 1.200 1.000 Passivo Circulante 900 750 Disponibilidades 150 120 Fornecedores a pagar 200 300 Contas a Receber 250 280 Salários a pagar 700 450 Estoques 800 600 Passivo Não Circulante 1.400 1.200 Ativo Não Circulante 2.800 2.500 Patrimônio Líquido (PL) 1.700 1.550 Total do Ativo 4.000 3.500 Total do Passivo + PL 4.000 3.500 Os dados abaixo foram extraídos da Demonstração do Resultado do Exercício (DRE) em 31/12/2025: ■ Despesas Operacionais: R$ 1.200 ■ Resultado (Lucro) Líquido do Exercício: R$ 350 ■ Lucro Bruto: R$ 1.800 ■ Receita Líquida de Vendas: R$ 4.500 Com base nas informações da Companhia Goiás e nos conhecimentos sobre a análise das demonstrações contábeis, é correto afirmar que a análise:','[["A","Vertical de 2025 da DRE demonstra margens brutas e líquidas positivas, que foram proporcionadas pela redução do saldo de R$ 300 para R$ 200 da conta Fornecedores a pagar."],["B","Vertical de 2025 mostra que o ativo não circulante representa 70% do ativo total e o passivo não circulante corresponde a 35% dos recursos totais, evidenciando que a origem de recursos foi financiada pelo lucro líquido de R$ 350."],["C","Diagonal de 2025 evidencia que a variação positiva do patrimônio líquido é explicada pela proporção das despesas operacionais em relação à receita líquida de vendas."],["D","Horizontal de 2024 demonstra que o passivo não circulante representa 1,2 do ativo circulante, o que revela uma tendência de geração de resultados positivos (lucros) em 2025, o que de fato ocorreu."],["E","Horizontal mostra que o ativo circulante e o passivo circulante cresceram 20%, enquanto o patrimônio líquido variou 9,68%. O índice de liquidez corrente permaneceu estável, mas houve aumento da participação de capital de terceiros."]]'::jsonb,'E',2026,420,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — Horizontal mostra que o ativo circulante e o passivo circulante cresceram 20%, enquanto o patrimônio líquido variou 9,68%. O índice de liquidez corrente permaneceu estável, mas houve aumento da participação de capital de terceiros.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis"}'::jsonb,'Considere o balanço patrimonial abaixo da Companhia Goiás: Companhia Goiás – Balanço Patrimonial – Valores em R$ ATIVO 31/12/2025 31/12/2024 PASSIVO e PL 31/12/2025 31/12/2024 Ativo Circulante 1.200 1.000 Passivo Circulante 900 750 Disponibilidades 150 120 Fornecedores a pagar...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year,