INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3983618',2110,83,'P1','Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis','QUADRIX - Ana (CREFITO 17)/CREFITO 17/Contábil/2026','Caderno Contabilidade Geral Parte 3','Considere‑se a tabela a seguir. Com base nessa situação hipotética e considerando que os dados apresentados foram fornecidos pela área contábil da Alfa & Ômega S.A., que seria uma sociedade empresária atuante no segmento comercial, para fins de análise e apuração contábil, julgue o item a seguir. A análise vertical do balanço patrimonial da Alfa & Ômega S.A. em 2024 revela que o ativo circulante representa 40% do ativo total, indicando que a maior parte dos recursos da empresa está concentrada em ativos de curto prazo.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Errado',2026,421,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Errado."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Errado — Errado","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis"}'::jsonb,'Considere‑se a tabela a seguir. Com base nessa situação hipotética e considerando que os dados apresentados foram fornecidos pela área contábil da Alfa & Ômega S.A., que seria uma sociedade empresária atuante no segmento comercial, para fins de análise e apuração contábil, jul...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
