INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3806444',2112,83,'P1','Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis','FGV - Per OC (PC PI)/PC PI/Perito Criminal/Contabilidade ou Economia/2026','Caderno Contabilidade Geral Parte 3','Em 31/12/2024, uma sociedade empresária apresentava os seguintes saldos em seu Balanço Patrimonial: Disponibilidades: R$100.000; Capital Social: R$100.000. Em janeiro de 2025, aconteceram os seguintes fatos: Pagamento de aluguel de dezembro de 2024: R$5.000. Compra de estoque à vista: R$60.000. Reconhecimento da venda de metade do estoque comprado no mês, com recebimento previsto para o mês seguinte e estimativa de inadimplência de 3%: R$90.000 Reconhecimento da despesa de aluguel e de salários, para pagamento no mês seguinte: R$20.000. Considerando apenas os fatos, ao realizar a análise vertical da Demonstração do Resultado, o perito constatou que o Lucro Líquido representava a seguinte porcentagem da Receita de Vendas','[["A","35,89%."],["B","38,89%."],["C","41,44%."],["D","44,44%."],["E","58,11%."]]'::jsonb,'C',2026,423,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — 41,44%.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis"}'::jsonb,'Em 31/12/2024, uma sociedade empresária apresentava os seguintes saldos em seu Balanço Patrimonial: Disponibilidades: R$100.000; Capital Social: R$100.000. Em janeiro de 2025, aconteceram os seguintes fatos: Pagamento de aluguel de dezembro de 2024: R$5.000. Compra de estoque ...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3830928',2113,83,'P1','Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis','CEBRASPE (CESPE) - Esp GT (TELEBRAS)/TELEBRAS/Analista Superior/Finanças/2026','Caderno Contabilidade Geral Parte 3','Em relação à análise econômico-financeira de uma entidade, julgue o item a seguir. A análise vertical requer que o analista considere mais de um período contábil, enquanto a análise horizontal pode ser realizada com base nas demonstrações contábeis relativas a um único período contábil.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Errado',2026,424,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Errado."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Errado — Errado","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis"}'::jsonb,'Em relação à análise econômico-financeira de uma entidade, julgue o item a seguir. A análise vertical requer que o analista considere mais de um período contábil, enquanto a análise horizontal pode ser realizada com base nas demonstrações contábeis relativas a um único período...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3959693',2114,83,'P1','Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis','FEPESE - Ag Neg (InvestSC)/InvestSC/Analista de Negócios/2026','Caderno Contabilidade Geral Parte 3','Analise o texto abaixo: Observando os constructos da análise de demonstrações financeiras, tem-se que análise ____________ é compreendida como o instrumental que calcula a variação percentual ocorrida de um período para outro, buscando compreender se houve crescimento ou decréscimo do item analisado. Por meio da análise dos dados, é possível perceber se houve aumento ou diminuição do elemento observado, assim como confrontar os dados extraídos e realizar as correlações necessárias. (Cavalcante, 2017) Assinale a alternativa que completa corretamente a lacuna do texto.','[["A","Vertical"],["B","Horizontal"],["C","por Índices de liquidez"],["D","por Índices de rentabilidade"],["E","por Índices de endividamento"]]'::jsonb,'B',2026,425,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Horizontal","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis"}'::jsonb,'Analise o texto abaixo: Observando os constructos da análise de demonstrações financeiras, tem-se que análise ____________ é compreendida como o instrumental que calcula a variação percentual ocorrida de um período para outro, buscando compreender se houve crescimento ou decré...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
