INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4045238',2118,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','Instituto AVALIA - Ana Trans (DETRAN RN)/DETRAN RN/Contabilidade/2026','Caderno Contabilidade Geral Parte 3','Cia. Solaris, uma empresa industrial do ramo de painéis solares, apresentou, em 31/12/2025, os seguintes dados no seu Balanço Patrimonial: ativo circulante: R$ 3.800.000; passivo circulante: R$ 2.200.000; patrimônio líquido: R$ 750.000. Com base nos dados fornecidos, assinale a alternativa que apresenta o valor mais aproximado do Índice de Liquidez Corrente da Cia. Solaris em 31/12/2025.','[["A","1,72."],["B","1,38."],["C","1,28."],["D","2,62."],["E","1,47."]]'::jsonb,'A',2026,431,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — 1,72.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'Cia. Solaris, uma empresa industrial do ramo de painéis solares, apresentou, em 31/12/2025, os seguintes dados no seu Balanço Patrimonial: ativo circulante: R$ 3.800.000; passivo circulante: R$ 2.200.000; patrimônio líquido: R$ 750.000. Com base nos dados fornecidos, assinale ...') ON CONFLICT (id) DO 