_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4026456',2120,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','IGEDUC - ENS (TRF 5)/TRF 5/Administração/2026','Caderno Contabilidade Geral Parte 3','A liquidez de uma organização está relacionada à sua capacidade de:','[["A","Expandir operações internacionais."],["B","Produzir em larga escala."],["C","Cumprir suas obrigações financeiras nos prazos estabelecidos."],["D","Aumentar sua participação de mercado."],["E","Elevar o número de empregados."]]'::jsonb,'C',2026,433,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Cumprir suas obrigações financeiras nos prazos estabelecidos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'A liquidez de uma organização está relacionada à sua capacidade de:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EX