INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3989270',2121,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','FUNDATEC - AgAdm (Pref Pinheiro Preto)/Pref Pinheiro Preto/2026','Caderno Contabilidade Geral Parte 3','A respeito dos indicadores de liquidez – liquidez imediata, seca, corrente e geral – assinale a alternativa correta.','[["A","A liquidez seca é sempre superior à liquidez corrente, pois exclui elementos de baixa liquidez, tornando o índice mais conservador."],["B","A liquidez imediata considera apenas disponibilidades, sendo o indicador mais restritivo, mas, isoladamente, não considera os demais ativos realizáveis no curto prazo."],["C","A liquidez geral avalia exclusivamente a capacidade de pagamento de curto prazo, sendo equivalente à liquidez corrente quando não há passivo não circulante."],["D","A liquidez corrente elimina os efeitos de ativos de difícil realização, sendo o melhor indicador para a avaliação da solvência imediata."]]'::jsonb,'B',2026,434,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — A liquidez imediata considera apenas disponibilidades, sendo o indicador mais restritivo, mas, isoladamente, não considera os demais ativos realizáveis no curto prazo.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'A respeito dos indicadores de liquidez – liquidez imediata, seca, corrente e geral – assinale a alternativa correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3961277',2122,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','Legalle - Tec Desen (BADESUL)/BADESUL/Contador/2026','Caderno Contabilidade Geral Parte 3','O Contador foi demandado para determinar o Índice de Liquidez Corrente de uma certa sociedade empresarial, num procedimento de concessão de empréstimo de longo prazo, que ao encerrar o exercício social em 31 de dezembro de 2025, apresentou as seguintes informações: Ativo Não Circulante: R$ 160.000. Passivo Circulante: R$ 200.000. Passivo Não Circulante: R$ 300.000. Patrimônio Líquido: R$ 360.000. Capital Circulante Líquido: R$ 500.000. Com base nessas informações, é CORRETO afirmar que o Índice de Liquidez Corrente foi de:','[["A","3,5."],["B","2,5."],["C","3,0."],["D","2,0."],["E","1,5."]]'::jsonb,'A',2026,435,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — 3,5.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'O Contador foi demandado para determinar o Índice de Liquidez Corrente de uma certa sociedade empresarial, num procedimento de concessão de empréstimo de longo prazo, que ao encerrar o exercício social em 31 de dezembro de 2025, apresentou as seguintes informações: Ativo Não C...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3977592',2123,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','INAZ do Pará - Cont (Pref Mazagão)/Pref Mazagão/2026','Caderno Contabilidade Geral Parte 3','Uma análise econômico-financeira foi elaborada a partir das demonstrações contábeis de uma entidade, com o objetivo de subsidiar decisões de gestão sobre liquidez, estrutura de capital e desempenho. O relatório apresenta, de forma sintética, os seguintes indicadores comparativos entre dois exercícios consecutivos: Liquidez Corrente: 1,6 → 1,0. Liquidez Seca: 1,1 → 0,6. Endividamento Geral (Passivo/Ativo): 50% → 68%. Margem Líquida: 8% → 5%. ROE (Retorno sobre o Patrimônio Líquido): 14% → 10%. Considerando o significado e a leitura integrada desses índices, identifique a alternativa CORRETA.','[["A","O aumento do endividamento geral, acompanhado de elevação do ROE, indica uso mais eficiente de capital de terceiros, mantendo liquidez adequada em razão da liquidez corrente igual a 1,0."],["B","A queda simultânea da liquidez corrente e da liquidez seca, associada ao aumento do endividamento geral, sugere maior pressão financeira de curto prazo e maior dependência de capital de terceiros."],["C","A redução da margem líquida, combinada com a elevação do endividamento geral, implica necessariamente aumento do lucro líquido em termos absolutos, com melhora do retorno ao acionista no período."],["D","A manutenção da liquidez corrente em 1,0 e a queda da liquidez seca para 0,6 caracterizam expansão do capital de giro próprio, sinalizando redução do risco financeiro apesar do aumento do endividamento."],["E","A queda do ROE, em conjunto com a redução do endividamento geral, evidencia desalavancagem e fortalecimento da solvência, coerentes com o avanço da liquidez seca no período."]]'::jsonb,'B',2026,436,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — A queda simultânea da liquidez corrente e da liquidez seca, associada ao aumento do endividamento geral, sugere maior pressão financeira de curto prazo e maior dependência de capital de terceiros.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'Uma análise econômico-financeira foi elaborada a partir das demonstrações contábeis de uma entidade, com o objetivo de subsidiar decisões de gestão sobre liquidez, estrutura de capital e desempenho. O relatório apresenta, de forma sintética, os seguintes indicadores comparativ...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3988410',2124,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','Instituto ACCESS - Adm (UFFS)/UFFS/2026','Caderno Contabilidade Geral Parte 3','Uma entidade pública empresarial busca melhorar sua liquidez operacional sem comprometer sua capacidade de atendimento. Para isso, passou a monitorar indicadores relacionados ao ciclo financeiro, incluindo prazos médios de estocagem, recebimento e pagamento. Considerando a Administração do Capital de Giro, assinale a alternativa INCORRETA:','[["A","O ciclo financeiro corresponde ao período entre o pagamento aos fornecedores e o recebimento das vendas, sendo influenciado pelos prazos operacionais."],["B","O aumento do prazo médio de pagamento a fornecedores pode contribuir para a redução do ciclo financeiro da organização."],["C","A gestão eficiente do capital de giro envolve o equilíbrio entre liquidez e rentabilidade, evitando tanto excessos quanto insuficiência de recursos."],["D","A redução do prazo médio de recebimento tende a diminuir a necessidade de financiamento do capital de giro."],["E","O aumento simultâneo dos prazos médios de estocagem e de recebimento, sem alteração no prazo de pagamento, reduz a necessidade de capital de giro."]]'::jsonb,'E',2026,437,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — O aumento simultâneo dos prazos médios de estocagem e de recebimento, sem alteração no prazo de pagamento, reduz a necessidade de capital de giro.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'Uma entidade pública empresarial busca melhorar sua liquidez operacional sem comprometer sua capacidade de atendimento. Para isso, passou a monitorar indicadores relacionados ao ciclo financeiro, incluindo prazos médios de estocagem, recebimento e pagamento. Considerando a Adm...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3983622',2125,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','QUADRIX - Ana (CREFITO 17)/CREFITO 17/Contábil/2026','Caderno Contabilidade Geral Parte 3','Considere‑se a tabela a seguir. Com base nessa situação hipotética e considerando que os dados apresentados foram fornecidos pela área contábil da Alfa & Ômega S.A., que seria uma sociedade empresária atuante no segmento comercial, para fins de análise e apuração contábil, julgue o item a seguir. O capital circulante líquido (CCL) da Alfa & Ômega S.A. em 2024, calculado pela diferença entre o ativocirculante e o passivo circulante, é de R$ 3.000 mil, sendo esse um valor positivo que indica que a empresa possui folga financeira de curto prazo, pois seus ativos circulantes são suficientes para cobrir as obrigações de curto prazo com sobra de recursos.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Certo',2026,438,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Certo."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Certo — Certo","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'Considere‑se a tabela a seguir. Com base nessa situação hipotética e considerando que os dados apresentados foram fornecidos pela área contábil da Alfa & Ômega S.A., que seria uma sociedade empresária atuante no segmento comercial, para fins de análise e apuração contábil, jul...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3977614',2126,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','INAZ do Pará - Cont (Pref Mazagão)/Pref Mazagão/2026','Caderno Contabilidade Geral Parte 3','Para análise de liquidez e gestão de curto prazo, considere as seguintes informações sintéticas (em R$) ao final de dois períodos consecutivos: Ativo Circulante (AC): 400.000 → 420.000. Passivo Circulante (PC): 250.000 → 280.000. Estoques: 120.000 → 150.000. Disponibilidades (Caixa e equivalentes): 60.000 → 40.000. Com base nesses dados e na leitura integrada de capital de giro e indicadores, indique a alternativa INCORRETA.','[["A","O capital de giro líquido (AC − PC) passou de 150.000 para 140.000, indicando redução do colchão de curto prazo."],["B","A liquidez corrente se reduziu de 1,60 para 1,50, sugerindo piora relativa na capacidade de cobertura do passivo de curto prazo."],["C","A elevação de estoques, associada à redução de disponibilidades, é compatível com pressão sobre caixa, ainda que o ativo circulante tenha aumentado."],["D","A redução do capital de giro líquido implica, por si só, aumento do lucro líquido no período, pois representa maior eficiência na utilização de recursos de curto prazo."],["E","A queda de disponibilidades pode ocorrer mesmo com aumento do ativo circulante, dependendo da composição do circulante e da forma de financiamento do crescimento."]]'::jsonb,'D',2026,439,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — A redução do capital de giro líquido implica, por si só, aumento do lucro líquido no período, pois representa maior eficiência na utilização de recursos de curto prazo.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'Para análise de liquidez e gestão de curto prazo, considere as seguintes informações sintéticas (em R$) ao final de dois períodos consecutivos: Ativo Circulante (AC): 400.000 → 420.000. Passivo Circulante (PC): 250.000 → 280.000. Estoques: 120.000 → 150.000. Disponibilidades (...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3987170',2127,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','FUNDATEC - Cont (Pref Araquari)/Pref Araquari/2026','Caderno Contabilidade Geral Parte 3','Uma entidade apresentou, ao final de determinado exercício, os seguintes dados extraídos de suas demonstrações contábeis: Ativo Circulante: R$ 300.000 Ativo Não Circulante: R$ 700.000 Passivo Circulante: R$ 200.000 Passivo Não Circulante: R$ 400.000 Patrimônio Líquido: R$ 400.000 Com base nessas informações, um analista concluiu corretamente que:','[["A","A entidade apresenta liquidez corrente inferior a 1 e elevado grau de dependência de capital de terceiros."],["B","A entidade possui liquidez corrente superior a 1 e estrutura de capital com predominância de recursos próprios."],["C","A entidade apresenta liquidez corrente superior a 1 e grau de endividamento, em relação ao ativo, superior a 50% do ativo total."],["D","A entidade possui liquidez corrente igual a 1 e equilíbrio entre capital próprio e de terceiros."]]'::jsonb,'C',2026,440,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — A entidade apresenta liquidez corrente superior a 1 e grau de endividamento, em relação ao ativo, superior a 50% do ativo total.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'Uma entidade apresentou, ao final de determinado exercício, os seguintes dados extraídos de suas demonstrações contábeis: Ativo Circulante: R$ 300.000 Ativo Não Circulante: R$ 700.000 Passivo Circulante: R$ 200.000 Passivo Não Circulante: R$ 400.000 Patrimônio Líquido: R$ 400....') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
