INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3986369',2129,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','Fênix Instituto - Age Adm (SIMAE Capinzal-Ouro)/SIMAE Capinzal-Ouro/2026','Caderno Contabilidade Geral Parte 3','Ao analisar as demonstrações contábeis do SIMAE, o setor administrativo verifica a capacidade de a entidade cumprir obrigações de curto prazo com recursos realizáveis também no curto prazo. O indicador mais diretamente relacionado a essa análise é o índice de:','[["A","Liquidez seca."],["B","Liquidez geral."],["C","Solvência geral."],["D","Liquidez corrente."]]'::jsonb,'D',2026,442,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Liquidez corrente.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'Ao analisar as demonstrações contábeis do SIMAE, o setor administrativo verifica a capacidade de a entidade cumprir obrigações de curto prazo com recursos realizáveis também no curto prazo. O indicador mais diretamente relacionado a essa análise é o índice de:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EX