INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3987163',2130,83,'P1','Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido','FUNDATEC - Cont (Pref Araquari)/Pref Araquari/2026','Caderno Contabilidade Geral Parte 3','No âmbito da análise das demonstrações contábeis, um analista avaliou que determinada entidade apresentou redução da liquidez corrente e aumento do índice de endividamento, mantendo constante o ativo total no período. Considerando os indicadores econômico-financeiros, assinale a alternativa que melhor explica essa situação.','[["A","A elevação do passivo não circulante, sem alteração do passivo circulante, reduz a liquidez corrente e eleva o endividamento total."],["B","O aumento de obrigações de curto prazo, sem correspondente incremento no ativo circulante, reduz a liquidez corrente e pode elevar o nível de endividamento."],["C","A redução do patrimônio líquido, com simultânea diminuição do ativo circulante, eleva a liquidez corrente e reduz o endividamento."],["D","O aumento das disponibilidades, acompanhado de elevação proporcional do passivo circulante, reduz a liquidez corrente e o índice de endividamento."]]'::jsonb,'B',2026,443,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — O aumento de obrigações de curto prazo, sem correspondente incremento no ativo circulante, reduz a liquidez corrente e pode elevar o nível de endividamento.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Liquidez. Capital Circulante Líquido"}'::jsonb,'No âmbito da análise das demonstrações contábeis, um analista avaliou que determinada entidade apresentou redução da liquidez corrente e aumento do índice de endividamento, mantendo constante o ativo total no período. Considerando os indicadores econômico-financeiros, assinale...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
