INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3627494',2138,83,'P1','Contabilidade Geral - Índices de Rentabilidade e Lucratividade','Instituto AOCP - Prof (SEDUC RS)/SEDUC RS/Administração/2025','Caderno Contabilidade Geral Parte 3','Uma empresa apresentou os seguintes dados em seu Balanço Patrimonial e na Demonstração de Resultados do Exercício (DRE) do ano de 2024: Ativo Circulante: R$ 320.000; Passivo Circulante: R$ 200.000; Ativo Total: R$ 850.000; Passivo Total: R$ 500.000; Patrimônio Líquido: R$ 350.000; Lucro Líquido: R$ 70.000. Com base nos dados fornecidos, assinale a alternativa que apresenta corretamente os resultados dos principais indicadores financeiros dessa empresa.','[["A","Liquidez corrente de 0,63; grau de endividamento de 1,42; rentabilidade sobre o patrimônio líquido de 15%."],["B","Liquidez corrente de 1,60; grau de endividamento de 0,58; rentabilidade sobre o patrimônio líquido de 20%."],["C","Liquidez corrente de 1,00; grau de endividamento de 0,70; rentabilidade sobre o patrimônio líquido de 18%."],["D","Liquidez corrente de 2,20; grau de endividamento de 0,30; rentabilidade sobre o patrimônio líquido de 10%."],["E","Liquidez corrente de 1,20; grau de endividamento de 0,95; rentabilidade sobre o patrimônio líquido de 22%."]]'::jsonb,'B',2025,474,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Rentabilidade e Lucratividade.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada