INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3681598',2142,83,'P1','Contabilidade Geral - Índices de Rentabilidade e Lucratividade','FUNDATEC - Ana Proj (BRDE)/BRDE/Contador/2025','Caderno Contabilidade Geral Parte 3','A Empresa Blue Garden S.A. apresentou, em 31/12/2024, um Ativo Circulante de R$ 2.080.000,00 e um Passivo Circulante de R$ 1.600.000,00. No mesmo exercício, o Patrimônio Líquido foi de R$ 2.400.000,00 e o Lucro Líquido registrado atingiu R$ 720.000,00, já considerando os devidos ajustes e padronizações contábeis para fins de análise. Com base nesses dados, os indicadores de Liquidez Corrente e Rentabilidade do PL foram, respectivamente:','[["A","1,2 e 28%."],["B","1,2 e 30%."],["C","1,3 e 28%."],["D","1,3 e 30%."],["E","1,4 e 32%."]]'::jsonb,'D',2025,479,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Rentabilidade e Lucratividade.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — 1,3 e 30%.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Rentabilidade e Lucratividade"}'::jsonb,'A Empresa Blue Garden S.A. apresentou, em 31/12/2024, um Ativo Circulante de R$ 2.080.000,00 e um Passivo Circulante de R$ 1.600.000,00. No mesmo exercício, o Patrimônio Líquido foi de R$ 2.400.000,00 e o Lucro Líquido registrado atingiu R$ 720.000,00, já considerando os devid...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3528396',2143,83,'P1','Contabilidade Geral - Índices de Rentabilidade e Lucratividade','Instituto CONSULPAM - Asst (CONAB)/CONAB/Contabilidade/2025','Caderno Contabilidade Geral Parte 3','O índice de rentabilidade do patrimônio líquido mede o retorno auferido pelos acionistas. Assinale a alternativa que apresenta CORRETAMENTE essa relação.','[["A","Lucro líquido dividido pelo patrimônio líquido médio."],["B","Patrimônio líquido dividido pelo ativo total."],["C","Lucro bruto sobre passivo exigível total."],["D","Receita líquida sobre despesas com pessoal."]]'::jsonb,'A',2025,480,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Rentabilidade e Lucratividade.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Lucro líquido dividido pelo patrimônio líquido médio.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Rentabilidade e Lucratividade"}'::jsonb,'O índice de rentabilidade do patrimônio líquido mede o retorno auferido pelos acionistas. Assinale a alternativa que apresenta CORRETAMENTE essa relação.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4026386',2144,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','IGEDUC - ENS (TRF 5)/TRF 5/Administração/2026','Caderno Contabilidade Geral Parte 3','O capital de giro corresponde aos recursos necessários para:','[["A","Aquisição exclusiva de imóveis."],["B","Financiamento das operações correntes da organização."],["C","Pagamento apenas de tributos."],["D","Expansão internacional da empresa."],["E","Aquisição de participações societárias."]]'::jsonb,'B',2026,484,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Financiamento das operações correntes da organização.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'O capital de giro corresponde aos recursos necessários para:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summ