INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3934074',2146,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','SELECON - TPN (EMGEPRON)/EMGEPRON/Técnico de Contabilidade/2026','Caderno Contabilidade Geral Parte 3','O balanço patrimonial da empresa demonstrou o montante ativo total no valor de R$ 10.000,00, enquanto o passivo total correspondeu a R$ 5.000,00. Com base nesses dados, é possível concluir que o índice de:','[["A","rotatividade equivale a 50%"],["B","liquidez seca equivale a 50%"],["C","liquidez geral equivale a 50%"],["D","endividamento equivale a 50%"]]'::jsonb,'D',2026,486,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — endividamento equivale a 50%","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'O balanço patrimonial da empresa demonstrou o montante ativo total no valor de R$ 10.000,00, enquanto o passivo total correspondeu a R$ 5.000,00. Com base nesses dados, é possível concluir que o índice de:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.f