INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3831193',2147,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','CEBRASPE (CESPE) - Esp GT (TELEBRAS)/TELEBRAS/Contador/2026','Caderno Contabilidade Geral Parte 3','Em relação à análise econômico-financeira de uma entidade, julgue o item seguinte. Em uma sociedade por ações, a subscrição de capital pelos sócios é uma transação que não afeta o indicador participação de capital de terceiros.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Certo',2026,487,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Certo."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Certo — Certo","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'Em relação à análise econômico-financeira de uma entidade, julgue o item seguinte. Em uma sociedade por ações, a subscrição de capital pelos sócios é uma transação que não afeta o indicador participação de capital de terceiros.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer,