INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3830926',2148,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','CEBRASPE (CESPE) - Esp GT (TELEBRAS)/TELEBRAS/Analista Superior/Finanças/2026','Caderno Contabilidade Geral Parte 3','Em relação à análise econômico-financeira de uma entidade, julgue o item a seguir. O valor do indicador participação de capital de terceiros sobre os recursos totais de uma sociedade por ações não será alterado quando houver a deliberação da distribuição de dividendos aos acionistas dessa sociedade.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Errado',2026,488,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Errado."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Errado — Errado","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'Em relação à análise econômico-financeira de uma entidade, julgue o item a seguir. O valor do indicador participação de capital de terceiros sobre os recursos totais de uma sociedade por ações não será alterado quando houver a deliberação da distribuição de dividendos aos acio...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3814611',2149,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','FGV - TDTND/AMAZUL/Técnico em Contabilidade/2026','Caderno Contabilidade Geral Parte 3','Em 2025, os sócios de uma sociedade empresária aumentaram o seu capital social, integralizando R$50.000 em dinheiro. Considerando apenas este fato, é esperado que o aumento no capital social traga o seguinte efeito no indicador de endividamento geral:','[["A","aumento, uma vez que o ativo total é maior."],["B","não há alteração, uma vez que o passivo permanece igual."],["C","não há alteração, uma vez que há aumento no ativo e no patrimônio líquido."],["D","diminuição, uma vez que a parcela do ativo total que é financiada por capital de terceiros é menor."],["E","diminuição, uma vez que o aumento no saldo do capital próprio traz uma diminuição no saldo do capital de terceiros."]]'::jsonb,'D',2026,489,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — diminuição, uma vez que a parcela do ativo total que é financiada por capital de terceiros é menor.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'Em 2025, os sócios de uma sociedade empresária aumentaram o seu capital social, integralizando R$50.000 em dinheiro. Considerando apenas este fato, é esperado que o aumento no capital social traga o seguinte efeito no indicador de endividamento geral:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3994435',2150,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','FGV - AFCE (TCE-SC)/TCE SC/Ciências Contábeis/2026','Caderno Contabilidade Geral Parte 3','Em 30/11/2025, uma entidade apresentava os seguintes saldos em seu Balanço Patrimonial: Disponibilidades: R$ 90.000,00; Terrenos destinados ao uso: R$ 210.000,00; Patrimônio Líquido: R$ 300.000,00. A entidade possuía 3 terrenos, sendo cada um avaliado por R$ 70.000,00. Em dezembro de 2025, a entidade decidiu concentrar as suas atividades em apenas um terreno. Desse modo, colocou os outros dois terrenos à venda, por R$ 72.000,00 cada. O nível hierárquico de gestão apropriado estava comprometido com o plano de venda dos terrenos, e iniciou um programa firme para localizar um comprador e concluir o plano assim que os terrenos estiverem desocupados, em fevereiro de 2027. A imobilização do patrimônio líquido da entidade, em 31/12/2025, foi de','[["A","23,33%."],["B","24,00%."],["C","70,00%."],["D","71,33%."],["E","72,00%."]]'::jsonb,'C',2026,490,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — 70,00%.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'Em 30/11/2025, uma entidade apresentava os seguintes saldos em seu Balanço Patrimonial: Disponibilidades: R$ 90.000,00; Terrenos destinados ao uso: R$ 210.000,00; Patrimônio Líquido: R$ 300.000,00. A entidade possuía 3 terrenos, sendo cada um avaliado por R$ 70.000,00. Em deze...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3799111',2151,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','IBADE - Cont (CREF 19)/CREF 19/2026','Caderno Contabilidade Geral Parte 3','Na análise de estrutura de capital, uma entidade apresenta passivo total de 600.000, patrimônio líquido de 400.000 e ativo total de 1.000.000. Assinale a alternativa correta sobre os indicadores de endividamento.','[["A","O endividamento geral é 0,4 e indica predominância de recursos próprios na estrutura do ativo."],["B","A participação de capital de terceiros é 0,6 e indica que as dívidas representam 60% do patrimônio líquido da entidade."],["C","A participação de capital de terceiros é 0,4 e indica que o passivo total equivale a 40% do ativo total do período."],["D","A participação de capital de terceiros é 1,5 e indica 1,5 de dívida para cada 1,0 de patrimônio líquido da entidade."],["E","O endividamento geral é 1,5 e indica que o ativo total é insuficiente para cobrir o passivo total no encerramento."]]'::jsonb,'D',2026,491,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — A participação de capital de terceiros é 1,5 e indica 1,5 de dívida para cada 1,0 de patrimônio líquido da entidade.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'Na análise de estrutura de capital, uma entidade apresenta passivo total de 600.000, patrimônio líquido de 400.000 e ativo total de 1.000.000. Assinale a alternativa correta sobre os indicadores de endividamento.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3852843',2152,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','FCM - CEFETMINAS - PEBTT (IF AM)/IF AM/Administração/2026','Caderno Contabilidade Geral Parte 3','A situação de endividamento de uma empresa indica o volume de dinheiro de terceiros usado para gerar lucros. De modo geral, o analista financeiro está mais preocupado com as dívidas de longo prazo porque estas comprometem a empresa com uma série de pagamentos contratuais ao longo do tempo. Uma medida comum ao grau de endividamento de uma empresa é o índice de endividamento. Em relação ao Índice de Endividamento Geral, é correto afirmar que seu cálculo é realizado pela divisão do','[["A","Lucro Operacional pela Receita de Vendas."],["B","Ativo Líquido Total pelo Passivo Circulante Total."],["C","Lucro antes de Juros e Imposto de Renda pelo valor dos Juros."],["D","Passivo Total pelo Ativo Total."],["E","Ativo Líquido Total pelo Passivo Total."]]'::jsonb,'D',2026,492,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Passivo Total pelo Ativo Total.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'A situação de endividamento de uma empresa indica o volume de dinheiro de terceiros usado para gerar lucros. De modo geral, o analista financeiro está mais preocupado com as dívidas de longo prazo porque estas comprometem a empresa com uma série de pagamentos contratuais ao lo...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3799114',2153,83,'P1','Contabilidade Geral - Estrutura de Capital e Índices de Endividamento','IBADE - Cont (CREF 19)/CREF 19/2026','Caderno Contabilidade Geral Parte 3','Na análise do ciclo operacional e do ciclo financeiro, considere: prazo médio de estocagem de 45 dias, prazo médio de recebimento de 30 dias e prazo médio de pagamento de 20 dias. Assinale a alternativa correta sobre os ciclos.','[["A","Ciclo operacional 55 dias e ciclo financeiro 35 dias, por subtração do prazo de pagamento do prazo de estocagem."],["B","Ciclo operacional 65 dias e ciclo financeiro 45 dias, por soma do prazo de pagamento com o prazo de recebimento."],["C","Ciclo operacional 75 dias e ciclo financeiro 55 dias, pela soma estocagem e recebimento menos o prazo de pagamento."],["D","Ciclo operacional 95 dias e ciclo financeiro 75 dias, por soma de estocagem, recebimento e pagamento no período."],["E","Ciclo operacional 75 dias e ciclo financeiro 95 dias, por inversão do prazo de pagamento para refletir o caixa."]]'::jsonb,'C',2026,493,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Estrutura de Capital e Índices de Endividamento.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Ciclo operacional 75 dias e ciclo financeiro 55 dias, pela soma estocagem e recebimento menos o prazo de pagamento.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Estrutura de Capital e Índices de Endividamento"}'::jsonb,'Na análise do ciclo operacional e do ciclo financeiro, considere: prazo médio de estocagem de 45 dias, prazo médio de recebimento de 30 dias e prazo médio de pagamento de 20 dias. Assinale a alternativa correta sobre os ciclos.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
