INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3992119',2158,69,'P2','Contabilidade Geral - Índices de Atividade (Rotação)','FGV - Bach (CFC)/CFC/1º Exame de Suficiência/2026','Caderno Contabilidade Geral Parte 3','Uma empresa fornece componentes tecnológicos para outras indústrias. Essa empresa adquire sua matéria-prima sempre a prazo, com pagamento médio em 20 dias. Em média, a empresa leva 70 dias para fabricar, armazenar e vender seus produtos. Ela vende somente a prazo, com pagamento em até 90 dias após a venda e, em média, leva 80 dias para receber após as vendas. Com base exclusivamente nesses dados, o ciclo operacional dessa empresa é de','[["A","70 dias."],["B","90 dias."],["C","150 dias."],["D","160 dias."]]'::jsonb,'C',2026,499,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Índices de Atividade (Rotação).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — 150 dias.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Índices de Atividade (Rotação)"}'::jsonb,'Uma empresa fornece componentes tecnológicos para outras indústrias. Essa empresa adquire sua matéria-prima sempre a prazo, com pagamento médio em 20 dias. Em média, a empresa leva 70 dias para fabricar, armazenar e vender seus produtos. Ela vende somente a prazo, com pagament...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
